"""Extract the fenced doc blocks in the five pinned files without changing assertions."""
from pathlib import Path
import collections, difflib, json, re

B = Path(__file__).resolve().parent
R = B.parent
H = 'generated by Codex gpt-6.1-sol on 2026-10-07 for Ivo Matijasevic'


def extract():
    blocks = []
    files = sorted((R / 'published/core-net-src-1.99.0').glob('*.rs'))
    assert len(files) == 5
    for p in files:
        opened = None
        for n, line in enumerate(p.read_text().splitlines(), 1):
            match = re.match(r'\s*//[/!](?: ?)(.*)', line)
            if not match:
                assert opened is None, (p.name, n, 'interrupted fence')
                continue
            text = match[1]
            fence = re.match(r'^\s*(`{3,}|~{3,})(.*)$', text)
            if opened is None and fence:
                opened = dict(file=p.name, line=n, fence=fence[1], info=fence[2].strip(), lines=[])
            elif opened is not None:
                if fence and fence[1][0] == opened['fence'][0] and len(fence[1]) >= len(opened['fence']) and not fence[2].strip():
                    opened['end_line'] = n
                    blocks.append(opened)
                    opened = None
                else:
                    opened['lines'].append((n, text))
        assert opened is None, p.name
    return blocks


def generate():
    rows, patch, tests = [], [], ['// ' + H + '\n']
    for block in extract():
        name = 'doc_' + block['file'].removesuffix('.rs') + '_' + str(block['line'])
        tags = set(re.split(r'[,\s]+', block['info'])) - {''}
        rewrites, hidden, code = [], [], []
        for n, line in block['lines']:
            # rustdoc includes hidden lines, and unescapes ## to a literal #.
            if line == '#' or line.startswith('# '):
                hidden.append(n)
                line = line[2:] if line.startswith('# ') else ''
            elif line.startswith('##'):
                line = line[1:]
            new = re.sub(r'\b(?:std|core)::net::', 'net_copy::net::', line)
            if new != line:
                rewrites.append(dict(line=n, before=line, after=new))
            code.append(new)
        original = '\n'.join(line for _, line in block['lines']) + '\n'
        source = '\n'.join(code) + '\n'
        reason = ''
        if tags & {'ignore', 'compile_fail', 'should_panic'} or any(t.startswith('ignore-') for t in tags):
            status, reason = 'skipped', 'Excluded as requested: ' + block['info']
        elif tags - {'rust', 'no_run', 'edition2015', 'edition2018', 'edition2021', 'edition2024'}:
            status, reason = 'non-rust', 'Explicit non-Rust fence: ' + block['info']
        elif '#![feature(' in source:
            status, reason = 'unported', 'Requires a nightly feature attribute; stable 1.99.0 rejects it (E0554). Removing it would exceed import-only rewriting. No RUSTC_BOOTSTRAP or nightly build is used.'
        else:
            assert 'fn main' not in source and '?' not in source and '#![' not in source, name
            status = 'ported'
            tests.append(f'// published/core-net-src-1.99.0/{block["file"]}:{block["line"]}\n#[test]\nfn {name}() {{\n')
            tests.append(''.join('    ' + line + '\n' for line in code))
            tests.append('}\n\n')
        rows.append(dict(id=name, file=block['file'], line=block['line'], end_line=block['end_line'], info=block['info'], status=status, reason=reason, hidden_lines=hidden, rewrites=rewrites, original=original, code=source))
        # The diff compares code after rustdoc's hidden-line interpretation; only imports change.
        interpreted = []
        for _, line in block['lines']:
            interpreted.append(line[2:] if line.startswith('# ') else '' if line == '#' else line[1:] if line.startswith('##') else line)
        patch.append(''.join(difflib.unified_diff(('\n'.join(interpreted)+'\n').splitlines(True), source.splitlines(True), fromfile=block['file']+':'+str(block['line']), tofile=name)))
    counts = dict(collections.Counter(row['status'] for row in rows))
    assert counts == {'ported': 80, 'non-rust': 4, 'unported': 24, 'skipped': 1}, counts
    (B / 'net-copy/tests/upstream_docs.rs').write_text(''.join(tests))
    (B / 'DOC-TEST-REWRITES.patch').write_text('# ' + H + '\n' + '\n'.join(patch))
    record = dict(provenance=H, files=[p.name for p in sorted((R/'published/core-net-src-1.99.0').glob('*.rs'))], counts=counts, blocks=rows)
    (B / 'doc-tests.json').write_text(json.dumps(record, indent=2) + '\n')
    text = '<!-- ' + H + ' -->\n# Source doc-test port\n\n'
    text += 'All 109 fenced blocks in the five pinned 1.99.0 files were extracted. 80 Rust examples run as separate tests against the copy: 55 from ip_addr.rs, 24 from socket_addr.rs, and one from parser.rs. mod.rs and display_buffer.rs contain no code fences. Only std::net:: and core::net:: import paths change. Assertions and input literals remain verbatim. The test wrapper supplies the implicit main body used by rustdoc. Hidden `# ` lines are included; `##` lines become literal `#` lines. This snapshot has no hidden lines.\n\n'
    text += 'The 24 examples with feature attributes cannot be ported under the stable, import-only rules. Their complete code is retained in [doc-tests.json](doc-tests.json). Six require addr_parse_ascii, three require ip_as_octets, and 15 require ip. No feature line is removed. Their stable compiler failures are recorded in evidence/gen/doc-unported-*.txt. These exclusions limit the meaning of the full upstream suite in this study. Four text/no_rust diagrams are not Rust tests. The should_panic example is skipped as requested; it would normally be a panic-expecting rustdoc test. No ignore or compile_fail block occurs in this snapshot.\n\n'
    text += '[DOC-TEST-REWRITES.patch](DOC-TEST-REWRITES.patch) records every import rewrite, including excluded blocks. [doc-tests.json](doc-tests.json) records original code, runnable code, source ranges, tags and disposition for every block. Extraction is replayed by run_all.sh before testing.\n\n| Source block | Status | Reason |\n| --- | --- | --- |\n'
    for row in rows:
        text += f'| `{row["file"]}:{row["line"]}` | {row["status"]} | {row["reason"] or row["id"]} |\n'
    (B / 'DOC-TESTS.md').write_text(text)
    print('DOC EXTRACTION PASS: 80 ported; 24 feature-gated unported; 4 non-Rust; 1 should_panic skipped')
    return record


def check_unported():
    """Keep real stable compiler failures for every feature-gated exclusion."""
    from runner import CARGO, ENV, run
    run('doc-unported-build', CARGO[:2] + ['build'] + CARGO[3:])
    libraries = sorted((B/'target/debug/deps').glob('libnet_copy-*.rlib'))
    assert libraries
    library = max(libraries, key=lambda p: p.stat().st_mtime_ns)
    folder = B/'evidence/gen/doc-unported'
    folder.mkdir(exist_ok=True)
    for row in json.loads((B/'doc-tests.json').read_text())['blocks']:
        if row['status'] != 'unported':
            continue
        code = row['code'].splitlines(True)
        attrs = [line for line in code if line.startswith('#![')]
        body = [line for line in code if not line.startswith('#![')]
        source = folder/(row['id']+'.rs')
        source.write_text('// '+H+'\n'+''.join(attrs)+'fn main() {\n'+''.join(body)+'}\n')
        result = run('doc-unported-'+row['id'], ['rustc', '+1.99.0', '--edition=2024', str(source), '--extern', 'net_copy='+str(library), '-L', 'dependency='+str(B/'target/debug/deps'), '--out-dir', str(folder)], expected=None)
        assert result.returncode != 0 and 'E0554' in result.stdout, row['id']
    print('DOC EXCLUSIONS PASS: 24 observed stable feature-gate failures')


if __name__ == '__main__':
    generate()
    check_unported()
